function is_palindrome(s : string) : bool {
    forall k :: 0 <= k < |s| ==> s[k] == s[|s| - 1 - k]
}
// pure-end
function starts_with(result : string, s : string) : bool {
    |result| >= |s| && forall k :: 0 <= k < |s| ==> result[k] == s[k]
}
// pure-end
method make_palindrome(s: string) returns (result: string)
    // post-conditions-start
    ensures |result| <= 2 * |s|
    ensures is_palindrome(result)
    ensures starts_with(result, s)
    // post-conditions-end
{
    var rev := reverse(s);
    result := s + rev;
    forall k | 0 <= k < |result|
        ensures result[k] == result[|result| - 1 - k]
    {
        if k < |s| {
            assert result[k] == s[k];
            assert result[|result| - 1 - k] == rev[|s| - 1 - k];
        } else {
            var j := k - |s|;
            assert result[k] == rev[j];
            assert result[|result| - 1 - k] == s[|s| - 1 - j];
        }
    }
}

method reverse(str: string) returns (rev: string)
    // post-conditions-start
    ensures |rev| == |str|
    ensures forall k :: 0 <= k < |str| ==> rev[k] == str[|str| - 1 - k]
    // post-conditions-end
{
    rev := [];
    var i := 0;
    while i < |str|
        invariant 0 <= i <= |str|
        invariant |rev| == i
        invariant forall k :: 0 <= k < i ==> rev[k] == str[|str| - 1 - k]
        decreases |str| - i
    {
        rev := rev + [str[|str| - 1 - i]];
        i := i + 1;
    }
}

